import java.util.function.*;
import java.util.*;

record Order(Long id, String customer, double amount, String status) {}

public class OrderProcessor {
    // Predicate: test condition
    Predicate<Order> isHighValue = order -> order.amount() > 1000;
    Predicate<Order> isPending = order -> "PENDING".equals(order.status());

    // Function: transform data
    Function<Order, String> toSummary = 
        order -> String.format("%s: $%.2f", order.customer(), order.amount());

    // Consumer: perform action
    Consumer<Order> sendNotification = 
        order -> System.out.println("Notifying " + order.customer());

    // Supplier: generate value
    Supplier<String> generateOrderId = 
        () -> "ORD-" + System.currentTimeMillis();

    public void processOrders(List<Order> orders) {
        orders.stream()
            .filter(isHighValue.and(isPending))  // Predicate
            .map(toSummary)                       // Function
            .forEach(System.out::println);        // Consumer

        var newId = generateOrderId.get();        // Supplier
    }
}

