@FunctionalInterface
interface OrderValidator {
    boolean validate(Order order);

    // This is allowed - default method with implementation
    default boolean validateAndLog(Order order) {
        var result = validate(order);
        System.out.println("Validation result: " + result);
        return result;
    }

    // Adding this would cause compile error with annotation:
    // boolean secondMethod(Order order);
}

// Historic functional interface without annotation
public class TaskRunner {
    public void execute(Runnable task) {  // Runnable has no @FunctionalInterface
        task.run();
    }

    public static void main(String[] args) {
        var runner = new TaskRunner();
        runner.execute(() -> System.out.println("Lambda works!"));
    }
}

import java.util.function.Predicate;
import java.util.List;

record Order(String id, double amount, String status, boolean isPriority) {}

public class OrderFilters {
    // Define simple, reusable predicates
    static Predicate<Order> isHighValue = order -> order.amount() > 1000;
    static Predicate<Order> isPending = order -> "PENDING".equals(order.status());
    static Predicate<Order> isPriority = Order::isPriority;
    static Predicate<Order> isLowValue = order -> order.amount() < 100;

    public static void main(String[] args) {
        var orders = List.of(
            new Order("A", 1500, "PENDING", true),
            new Order("B", 50, "PENDING", false),
            new Order("C", 2000, "SHIPPED", false)
        );

        // Compose: high value AND pending
        var urgentOrders = isHighValue.and(isPending);

        // Compose: priority OR high value
        var importantOrders = isPriority.or(isHighValue);

        // Negate: NOT low value
        var substantialOrders = isLowValue.negate();

        // Complex composition: (high value AND pending) OR priority
        var needsAttention = isHighValue.and(isPending).or(isPriority);

        var filtered = orders.stream()
            .filter(needsAttention)
            .toList();
    }
}

import java.util.function.Function;

record Order(String id, double basePrice, String customerType) {}

public class PricingPipeline {
    // Individual transformation functions
    static Function<Order, Double> extractBasePrice = Order::basePrice;
    static Function<Double, Double> applyTax = price -> price * 1.18;
    static Function<Double, Double> applyDiscount = price -> price * 0.9;
    static Function<Double, String> formatCurrency = 
        price -> String.format("$%.2f", price);

    public static void main(String[] args) {
        var order = new Order("ORD-001", 100.0, "PREMIUM");

        // Using andThen - reads left to right
        Function<Order, String> pricingPipeline = extractBasePrice
            .andThen(applyDiscount)    // 100 -> 90
            .andThen(applyTax)          // 90 -> 106.2
            .andThen(formatCurrency);   // 106.2 -> "$106.20"

        var finalPrice = pricingPipeline.apply(order);

        // Using compose - reads right to left (less intuitive)
        Function<Double, String> reverseChain = formatCurrency
            .compose(applyTax)      // apply tax first
            .compose(applyDiscount); // then discount

        var sameResult = reverseChain.apply(order.basePrice());

        System.out.println(finalPrice);  // "$106.20"
    }
}

import java.io.IOException;
import java.util.function.Function;

// Custom interface that throws checked exception
@FunctionalInterface
public interface FileProcessor<T, R> {
    R process(T input) throws IOException;  // Checked exception allowed

    // Default method for composition
    default <V> FileProcessor<T, V> andThen(FileProcessor<R, V> after) {
        return input -> {
            R intermediate = this.process(input);
            return after.process(intermediate);
        };
    }

    // Convert to standard Function by wrapping exceptions
    default Function<T, R> toFunction() {
        return input -> {
            try {
                return process(input);
            } catch (IOException e) {
                throw new RuntimeException("File processing failed", e);
            }
        };
    }
}

// Usage with lambda
public class DocumentService {
    FileProcessor<String, String> readFile = 
        path -> java.nio.file.Files.readString(java.nio.file.Path.of(path));

    FileProcessor<String, String> parseJson = 
        content -> content.toUpperCase();  // Simplified parsing

    public void processDocument(String path) throws IOException {
        var pipeline = readFile.andThen(parseJson);
        var result = pipeline.process(path);
        System.out.println(result);
    }
}

import java.util.function.*;
import java.util.stream.*;
import java.util.*;

public class PrimitiveStreamPerformance {

    public static void main(String[] args) {
        var numbers = IntStream.range(1, 1_000_000);

        // GOOD: Using primitive functional interfaces (no boxing)
        IntPredicate isEven = n -> n % 2 == 0;  // Works with primitive int
        IntUnaryOperator square = n -> n * n;   // int -> int, no boxing
        IntConsumer print = n -> System.out.println(n);  // Consumes int

        var result = numbers
            .filter(isEven)      // Uses IntPredicate
            .map(square)         // Uses IntUnaryOperator
            .limit(5)
            .sum();              // Returns primitive long

        // BAD: Using generic interfaces (boxing overhead)
        Predicate<Integer> boxedIsEven = n -> n % 2 == 0;  // Boxes every int
        Function<Integer, Integer> boxedSquare = n -> n * n;  // Creates Integer objects

        // Specialized conversion interfaces
        ToIntFunction<String> parseLength = String::length;  // String -> int
        IntFunction<String> formatInt = n -> "Number: " + n;  // int -> String

        var names = List.of("Alice", "Bob", "Charlie");
        var totalLength = names.stream()
            .mapToInt(parseLength)  // Converts to IntStream using ToIntFunction
            .sum();

        System.out.println("Total length: " + totalLength);
    }
}
